const worksByTMDB = `-- name: WorksByTMDB :many
SELECT work_id, tvdb_id, tmdb_id FROM series_series WHERE tmdb_id IN (/*SLICE:tmdb_ids*/?) ORDER BY tmdb_id
`

type WorksByTMDBRow struct {
	WorkID works.WorkID
	TvdbID TVDBID
	TmdbID *TMDBID
}

func (q *Queries) WorksByTMDB(ctx context.Context, tmdbIds []*TMDBID) ([]WorksByTMDBRow, error) {
	query := worksByTMDB
	var queryParams []interface{}
	if len(tmdbIds) > 0 {
		for _, v := range tmdbIds {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:tmdb_ids*/?", strings.Repeat(",?", len(tmdbIds))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:tmdb_ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []WorksByTMDBRow
	for rows.Next() {
		var i WorksByTMDBRow
		if err := rows.Scan(&i.WorkID, &i.TvdbID, &i.TmdbID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
